<template><main class="journeys-page"><header><span>TIME ROUTES</span><h1>旅行</h1><p>地点不是清单，而是记忆发生的顺序。</p></header><a-spin :spinning="loading"><section v-if="items.length" class="journey-list"><NuxtLink v-for="item in items" :key="item.id" :to="`/journeys/${item.slug}`"><img v-if="item.coverImage" :src="mediaUrl(item.coverImage)" alt=""><span v-else><Icon name="ph:path-bold" /></span><div><small>{{ item.stops.length }} 站</small><h2>{{ item.title }}</h2><p>{{ item.description }}</p></div><Icon name="ph:arrow-up-right-bold" /></NuxtLink></section><a-empty v-else-if="!loading" description="还没有公开旅行" /></a-spin></main></template>
<script setup lang="ts">const api=useApi();const {mediaUrl}=useMediaUrl();const loading=ref(true);const items=ref<any[]>([]);onMounted(async()=>{try{items.value=(await api.get<any>('/journeys',{limit:50})).items||[]}catch{items.value=[]}finally{loading.value=false}});useHead({title:'旅行'})</script>
<style scoped>.journeys-page{width:min(980px,calc(100% - 32px));margin:0 auto;padding:48px 0 80px}.journeys-page>header{margin-bottom:34px}.journeys-page>header span{color:var(--c-primary);font-size:.65rem;font-weight:750}.journeys-page h1{margin:8px 0 6px;color:var(--c-text);font-size:2.2rem}.journeys-page header p{color:var(--c-text-3)}.journey-list{border-top:1px solid var(--border)}.journey-list>a{display:grid;grid-template-columns:150px 1fr 28px;align-items:center;gap:22px;padding:18px 0;border-bottom:1px solid var(--border);color:inherit;text-decoration:none}.journey-list>a>img,.journey-list>a>span{width:150px;aspect-ratio:16/9;object-fit:cover;border-radius:6px;background:var(--c-bg-2)}.journey-list>a>span{display:grid;color:var(--c-primary);font-size:2rem;place-items:center}.journey-list small{color:var(--c-primary)}.journey-list h2{margin:5px 0;color:var(--c-text);font-size:1.1rem}.journey-list p{margin:0;color:var(--c-text-3);font-size:.78rem}@media(max-width:600px){.journey-list>a{grid-template-columns:90px 1fr 20px;gap:12px}.journey-list>a>img,.journey-list>a>span{width:90px}}</style>
